<script setup>
import { computed, ref, watch } from 'vue';
import { useRouter } from 'vue-router';
import { storeToRefs } from 'pinia';
import { useCarritoStore } from '../stores/carrito';
import { useTiendaUiStore } from '../stores/tiendaUi';
defineProps({ buscador:{type:Boolean,default:true} });
const router=useRouter(), carrito=useCarritoStore(), ui=useTiendaUiStore();
const {cantidadItems,ultimoAviso,avisoTipo,confirmacionId}=storeToRefs(carrito), {busqueda,categoria}=storeToRefs(ui);
const menuAbierto=ref(false), mostrarAviso=ref(false), animarCarrito=ref(false); let temporizador;
const cantidad=computed(()=>cantidadItems.value);
function irCategoria(valor){ui.seleccionarCategoria(valor);menuAbierto.value=false;router.push({path:'/tienda',hash:'#productos'});window.setTimeout(()=>document.querySelector('#productos')?.scrollIntoView({behavior:'smooth'}),50)}
function buscar(){if(busqueda.value.trim())irCategoria(categoria.value)}
watch(confirmacionId,()=>{mostrarAviso.value=true;animarCarrito.value=false;requestAnimationFrame(()=>animarCarrito.value=true);clearTimeout(temporizador);temporizador=setTimeout(()=>mostrarAviso.value=false,2800)});
</script>
<template><div class="tienda-shell"><header class="tienda-header"><router-link to="/tienda" class="tienda-logo">X-STORE</router-link><button class="menu-btn" :aria-expanded="menuAbierto" aria-label="Abrir navegación" @click="menuAbierto=!menuAbierto"><span class="material-symbols-outlined">{{menuAbierto?'close':'menu'}}</span></button><nav :class="['tienda-nav',{abierto:menuAbierto}]" aria-label="Catálogo"><button :class="{activo:categoria==='Todo'}" @click="irCategoria('Todo')">Tienda</button><button :class="{activo:categoria==='Videojuegos'}" @click="irCategoria('Videojuegos')">Juegos</button><button :class="{activo:['Consolas','Accesorios'].includes(categoria)}" @click="irCategoria('Consolas')">Hardware</button><router-link to="/tienda/servicio/1" @click="menuAbierto=false">Servicio técnico</router-link></nav><form v-if="buscador" class="tienda-search" role="search" @submit.prevent="buscar"><span class="material-symbols-outlined">search</span><input v-model="busqueda" aria-label="Buscar productos" placeholder="Buscar juegos, consolas, accesorios..."><button v-if="busqueda" type="button" aria-label="Limpiar búsqueda" @click="busqueda=''"><span class="material-symbols-outlined">close</span></button></form><div class="tienda-actions"><router-link to="/tienda/carrito" :class="['tienda-icon',{pulso:animarCarrito}]" :aria-label="`Carrito, ${cantidad} productos`"><span class="material-symbols-outlined">shopping_cart</span><strong v-if="cantidad">{{cantidad}}</strong></router-link><router-link to="/tienda/login" class="tienda-icon" aria-label="Cuenta"><span class="material-symbols-outlined">account_circle</span></router-link></div></header><main><slot/></main><transition name="aviso"><div v-if="mostrarAviso" :class="['toast',{error:avisoTipo==='error'}]" role="status" aria-live="polite"><span class="material-symbols-outlined">{{avisoTipo==='error'?'inventory_2':'check_circle'}}</span><div><strong>{{avisoTipo==='error'?'Stock insuficiente':'Agregado a tu selección'}}</strong><small>{{ultimoAviso}}</small></div><router-link to="/tienda/carrito">Ver carrito</router-link></div></transition><footer class="tienda-footer"><div><strong>X-STORE KINETIC</strong><span>© 2026. Todos los derechos reservados.</span></div><nav><a href="#">Privacidad</a><a href="#">Términos</a><a href="#">Soporte</a><router-link class="acceso-personal" to="/admin" aria-label="Acceder al panel de empleados"><span class="material-symbols-outlined">badge</span>Portal del personal</router-link></nav></footer></div></template>
